INSERT INTO `sys_goods` VALUES (1, '招牌麻辣烫*麻酱干拌', '默认带麻酱，新鲜食材，配送丰富小料搅拌均匀。一口吃下，有种火锅的味道。', 'data:image/png;base64,', 23.50, 10001, '招牌', 125, '2024-01-10 15:50:05', 1, '2024-01-10 15:49:36');
INSERT INTO `sys_goods` VALUES (2, '人气女神减脂餐【大份】', '包含：鸭血 豆泡 年糕片 鱼豆腐 木耳 蟹棒 粉丝 包菜。', 'data:image/png;base64,', 21.50, 10001, '招牌', 335, '2024-01-10 15:50:07', 0, '2024-01-10 15:49:39');
INSERT INTO `sys_goods` VALUES (3, '低卡蔬菜减脂套餐', '包含：冬瓜3片 千页豆腐2片 冻豆腐3个 小青菜30克 香菇丸2个 娃娃菜4个，小青菜30克。', 'data:image/png;base64,', 20.00, 10001, '爆火', 344, '2024-01-10 15:50:10', 1, '2024-01-10 15:49:41');
INSERT INTO `sys_goods` VALUES (4, '巴沙鱼什锦套餐【大份】', '主打：巴沙鱼配菜：豆芽 千张 冬瓜 木耳 土豆 鸭血 小青菜 魔芋结 西蓝花 金针菇。', 'data:image/png;base64,', 15.00, 10001, '', 327, '2024-01-10 15:50:12', 1, '2024-01-10 15:49:43');
INSERT INTO `sys_goods` VALUES (5, '开心果奶昔', '现打香草奶昔混合纯正开心果酱、薄脆片和自制咸蜂蜜，撒上开心果碎和薄脆片。', 'data:image/png;base64,', 48.00, 10002, '', 543, '2024-01-10 15:50:15', 1, '2024-01-10 15:49:46');
INSERT INTO `sys_goods` VALUES (6, '香辣烟熏培根牛肉堡', '芝士牛肉汉堡配苹果烟熏培根、红樱桃辣椒、主厨秘制酱料【建议1人食用】。', 'data:image/png;base64,', 59.00, 10002, '', 342, '2024-01-10 15:50:17', 1, '2024-01-10 15:49:48');
INSERT INTO `sys_goods` VALUES (7, '芝士牛肉蘑菇堡', '招牌牛肉堡+芝士蘑菇堡的双层体验，配新鲜生菜和番茄、主厨秘制酱料【建议1人食用】。', 'data:image/png;base64,', 84.00, 10002, '', 423, '2024-01-10 15:50:20', 1, '2024-01-10 15:49:50');
INSERT INTO `sys_goods` VALUES (8, '招牌炸鸡块', '采用鸡胸肉，香脆鸡块可选配BBQ酱料或蜂蜜芥末酱【建议1人食用】。', 'data:image/png;base64,', 36.00, 10002, '', 123, '2024-01-10 15:50:22', 0, '2024-01-10 15:49:52');
INSERT INTO `sys_goods` VALUES (17, '麦旋风™奥利奥原味', '冰淇淋的香滑与奥利奥饼干的香酥融为一体，奇妙黑白搭配，创造无限新奇滋味。', 'data:image/png;base64,', 12.00, 10003, '爆火', 998, '2024-06-23 16:54:05', 1, '2024-06-23 16:54:13');
INSERT INTO `sys_goods` VALUES (18, '圆筒冰淇淋', '醇香细腻的冰淇淋搭配香脆圆筒，将清甜与松脆一口咬下！', 'data:image/png;base64,', 8.00, 10003, '招牌', 126, '2024-06-23 16:55:35', 1, '2024-06-23 16:55:43');
