INSERT INTO `sys_goods` VALUES (35, '招牌小鲜肉', '精选猪肉猛火炙烤', 'data:image/png;base64,', 14.00, 10005, '招牌', 646, '2024-06-23 17:28:13', 1, '2024-06-23 17:28:19');
INSERT INTO `sys_goods` VALUES (36, '脆香掌中宝(10串)', '掌中宝又名鸡媵脆骨，一只鸡只又两小块，高含满满的胶原蛋白', 'data:image/png;base64,', 19.00, 10005, NULL, 666, '2024-06-23 17:30:03', 1, '2024-06-23 17:30:08');
INSERT INTO `sys_goods` VALUES (37, '酱爆牛肉(10串)', '新鲜的牛肉切成小片穿申，冷藏保证它的新鲜，很多人可口牛肉都会事先腌制，却不知道这样的牛肉己经失去了它的鲜味，我们是直接用新鲜牛肉烤制，途中刷酱不腌制，让你享受美味的同时更能体验到牛肉本身的鲜香。', 'data:image/png;base64,', 17.00, 10005, NULL, 989, '2024-06-23 17:31:10', 1, '2024-06-23 17:31:14');
INSERT INTO `sys_goods` VALUES (38, '酱骨约1斤+自选时蔬+米饭', '小店出餐的酱骨重量是生骨重量，炖煮后一斤出大约出八两多', 'data:image/png;base64,', 23.80, 10006, '招牌', 233, '2024-06-23 17:36:46', 1, '2024-06-23 17:36:49');
INSERT INTO `sys_goods` VALUES (39, '招牌酱骨+鸡腿+两种时蔬+米饭', '加入鸡腿分量十足', 'data:image/png;base64,', 24.80, 10006, NULL, 658, '2024-06-23 17:37:50', 1, '2024-06-23 17:37:55');
INSERT INTO `sys_goods` VALUES (40, '手撕大排+自选时蔬+米饭', '多肉', 'data:image/png;base64,', 26.80, 10006, NULL, 333, '2024-06-23 17:39:00', 1, '2024-06-23 17:39:04');
INSERT INTO `sys_goods` VALUES (41, '嘎嘣脆骨+自选时蔬+米饭', '脆骨', 'data:image/png;base64,', 24.50, 10006, NULL, 555, '2024-06-23 17:39:50', 1, '2024-06-23 17:39:56');
INSERT INTO `sys_goods` VALUES (42, '红茶拿铁', '优质红茶在蒸奶中慢慢的呈现出温和的口感，以柔和的奶泡锁住茶香，加以经典风味酱。这是红茶与牛奶的对话，优雅品享红茶文化。', 'data:image/jpeg;base64,', 38.80, 10007, '招牌', 334, '2024-06-23 17:51:06', 1, '2024-06-23 17:51:09');
INSERT INTO `sys_goods` VALUES (43, '冰摇红莓黑加仑茶', '红莓黑加仑果汁融合醇香冰红茶，两款风格各异的莓子与冰红茶摇出各自的果香，却又浑然一体，迷恋在莓与茶的酸甜中。', 'data:image/jpeg;base64,', 36.00, 10007, NULL, 556, '2024-06-23 17:51:56', 0, '2024-06-23 17:52:00');
INSERT INTO `sys_goods` VALUES (44, '抹茶拿铁', '优质抹茶、蒸奶以及细腻奶泡加以经典风味酱融合于一杯饮品，柔顺香甜，清雅脱俗。', 'data:image/jpeg;base64,', 38.80, 10007, NULL, 34, '2024-06-23 17:53:09', 1, '2024-06-23 17:53:13');
INSERT INTO `sys_goods` VALUES (45, '茶瓦纳™ 冰摇柚柚蜂蜜红茶', '混合了韩国柚子的清香、以色列柚汁的甘甜、西班牙粉柚汁的果香融于醇香红茶，颗颗饱满果粒和清甜柚子皮，点缀上蜂蜜层层深入的口感，让TA对这杯沁人心脾念念不忘 。', 'data:image/jpeg;base64,', 37.00, 10007, NULL, 24, '2024-06-23 17:54:33', 1, '2024-06-23 17:54:37');
INSERT INTO `sys_goods` VALUES (46, '招牌香酥鸡饼', '门店热销TOP:饼十香酥鸡十年糕。酥嫩鸡柳软耩年糕剧上秘制酱料，烧饼新吃法，超绝新体验。', 'data:image/png;base64,', 16.90, 10009, '招牌', 435, '2024-06-23 18:08:05', 1, '2024-06-23 18:08:08');
INSERT INTO `sys_goods` VALUES (47, '嫩汁厚切腿排饼', '厚厚的鸡腿', 'data:image/png;base64,', 17.90, 10009, NULL, 555, '2024-06-23 18:09:08', 1, '2024-06-23 18:09:12');
INSERT INTO `sys_goods` VALUES (48, '炉迹香酥鸡饼', '热销TOPI，招牌烧饼十香酥鸡十年糕(可加料)，鸡柳年糕微粉口感更多元丰言哦。匠心传承工艺，炉火悠悠香酥可口!\n买它买它', 'data:image/png;base64,', 17.90, 10009, NULL, 342, '2024-06-23 18:10:12', 1, '2024-06-23 18:10:15');
INSERT INTO `sys_goods` VALUES (49, '爱马仕万福羊羔串饼', '烧饼中的爱马仕加料款，加料刷秘酱吃货直喊棒。饼+盖羊申', 'data:image/png;base64,', 25.90, 10009, NULL, 600, '2024-06-23 18:11:07', 1, '2024-06-23 18:11:11');
INSERT INTO `sys_goods` VALUES (50, '葡式蛋挞(2只/6只装)', '面式蛋挞2只16只:而式经典，蛋奶香浓，抛皮酥胞:主要原料:挞皮、蛋液、淡奶油、牛奶。产品及包装以实物为准。', 'data:image/png;base64,', 39.00, 10010, NULL, 555, '2024-06-23 18:15:03', 0, '2024-06-23 18:15:08');
INSERT INTO `sys_goods` VALUES (51, 'K咖啡3杯任选', 'K咖啡3杯(可选)。产品及包装以实物为准。', 'data:image/png;base64,', 39.00, 10010, '特惠', 300, '2024-06-23 18:16:00', 1, '2024-06-23 18:16:04');
INSERT INTO `sys_goods` VALUES (52, '人气明星随心配', '主食1份(加价可选)+小食1份(可选)+甜品1份(加价可选)+饮品1杯(加价可选)。产品及包装以实物为准。', 'data:image/png;base64,', 46.00, 10010, NULL, 23, '2024-06-23 18:16:54', 1, '2024-06-23 18:16:57');
INSERT INTO `sys_goods` VALUES (53, '饼汉堡双人随心配', '滕椒风味鸡排饼汉堡1个+主食1份(可选)+小会3份(可选)+饮品2杯(可选)。主要原料:鸡肉、面饼、蔬菜(生菜、丝)。产品及包装以实物为准。', 'data:image/png;base64,', 78.00, 10010, NULL, 4, '2024-06-23 18:17:47', 1, '2024-06-23 18:17:51');
INSERT INTO `sys_goods` VALUES (59, '统一阿萨姆奶茶\n500ml/瓶', '统- 阿萨姆奶茶\n500ml/瓶', 'data:image/png;base64,', 4.00, 10008, NULL, 3, '2024-06-23 18:37:02', 1, '2024-06-23 18:37:05');
