-- ----------------------------
-- Table structure for sys_orders
-- ----------------------------
DROP TABLE IF EXISTS `sys_orders`;
CREATE TABLE `sys_orders`  (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单编号',
  `account_id` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '下单用户编号--sys_account表account_id\r\n',
  `business_id` bigint NOT NULL COMMENT '商家编号--sys_business表business_id',
  `created` datetime NOT NULL COMMENT '订购日期',
  `order_total` decimal(7, 2) NOT NULL DEFAULT 0.00 COMMENT '订单总价',
  `da_id` int NOT NULL COMMENT '送货地址编号--sys_deliveryaddress表da_id',
  `statu` int NOT NULL DEFAULT 0 COMMENT '订单状态（0：未支付； 1：已支付）',
  `updated` datetime NULL DEFAULT NULL COMMENT '订单更新时间',
  PRIMARY KEY (`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 199 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

